node --input-type=module -e "
import { loadEnv, botToken } from './src/config.mjs';
import { makeFetchJson } from './src/discordApi.mjs';

const channelId = '1533603278816936168';
const messageId = '1533623632008315084';
const env = await loadEnv();
const tok = botToken(env);
if (!tok) throw new Error('missing AVA_DISCORD_BOT_TOKEN');
const fetchJson = makeFetchJson(tok);

const target = await fetchJson('/channels/' + channelId + '/messages/' + messageId);
const around = await fetchJson('/channels/' + channelId + '/messages?around=' + messageId + '&limit=15');

function summarize(m) {
  return {
    id: m.id,
    author: m.author?.username + ' (' + m.author?.id + ')',
    bot: !!m.author?.bot,
    content: (m.content || '').slice(0, 1200),
    timestamp: m.timestamp,
    referenced: m.message_reference?.message_id || null,
    reactions: (m.reactions || []).map(r => ({ emoji: r.emoji?.name || r.emoji?.id, count: r.count })),
  };
}

console.log(JSON.stringify({
  target: summarize(target),
  around: (around || []).map(summarize).reverse(),
}, null, 2));

// soft-ack
for (const emoji of ['⏱️', '👀']) {
  const enc = encodeURIComponent(emoji);
  try {
    await fetchJson('/channels/' + channelId + '/messages/' + messageId + '/reactions/' + enc + '/@me', { method: 'PUT' });
    console.log('reacted', emoji);
  } catch (e) {
    console.warn('react fail', emoji, e.message);
  }
}
"
